VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,7.87,"Lecture seventeen. Spiking neural networks, which talk in brief spikes and stay quiet when nothing happens."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":25.008,"caps":[[0.5,5.23,"Pip patrols a garden on one coin battery."],[5.48,11.49,"A conventional ANN computes every neuron, every step."],[11.74,16.31,"Pip needs quick reactions, low power and learning on the go."],[16.56,24.17,"An SNN sends discrete spikes only when needed."]],"warp":[[0,0],[0.5,0.4],[5.48,3.2],[11.74,6],[16.56,8.8],[25.008,12]]},{"dur":23.336,"caps":[[0.5,6.03,"A neuron's run of spikes over time is a spike train."],[6.28,10.13,"Rate coding: a stronger signal sends more spikes."],[10.38,16.71,"Dim 2, medium 5, bright 9 spikes in 20 steps."],[16.96,21.93,"Only how many count, not their size."]],"warp":[[0,0],[0.5,0.4],[6.28,3.2],[10.38,6],[16.96,8.8],[23.336,12]]},{"dur":25.008,"caps":[[0.5,5.31,"Temporal coding: a strong input fires early, a weak one late."],[5.56,12.37,"Bright fires at step 4, dim at step 16. One spike can be enough."],[12.62,17.83,"Population coding: five neurons, each liking a range."],[18.08,23.37,"Strength 7 wakes the neurons that like 5, 7.5 and 10."]],"warp":[[0,0],[0.5,0.4],[5.56,3.2],[12.62,6],[18.08,9.6],[25.008,13]]},{"dur":28.328,"caps":[[0.5,8.75,"Charge accumulates from inputs, like drops in a bucket."],[9,16.77,"At the threshold it fires a spike, resets, and fills again."],[17.02,21.51,"Below-threshold charge leaks away over time."],[21.76,27.37,"With this leak the charge levels off near 0.67: no spike."]],"warp":[[0,0],[0.5,0.4],[9,3.6],[17.02,8],[21.76,11],[28.328,14]]},{"dur":26.657,"caps":[[0.5,5.47,"t = 1: input A fires."],[5.72,9.25,"t = 2: one step later, both of A's neighbours fire."],[9.5,14.87,"O needs 3 spikes at once. Two is not enough."],[15.12,19.29,"t = 4: A's and B's neighbours fire together."],[19.54,25.71,"t = 5: O gets 4 spikes, crosses its threshold and fires."]],"warp":[[0,0],[0.5,0.4],[5.72,2.4],[9.5,4.4],[15.12,6.6],[19.54,8.8],[26.657,13]]},{"dur":26.679,"caps":[[0.5,7.23,"A synapse links a pre-synaptic sender to a post-synaptic receiver."],[7.48,14.45,"Pre fires just before post: strengthen. Potentiation."],[14.7,19.35,"Post fires before pre: weaken. Depression."],[19.6,25.21,"No labels needed: STDP is unsupervised learning."]],"warp":[[0,0],[0.5,0.4],[7.48,3.2],[14.7,7.4],[19.6,10.6],[26.679,14]]},{"dur":23.336,"caps":[[0.5,5.79,"Backpropagation walks back from the error, using each neuron's slope."],[6.04,10.53,"A spiking neuron is 0 below the threshold, then jumps."],[10.78,16.31,"Its slope is the Dirac delta: zero everywhere but one point."],[16.56,22.49,"No gradient information, so plain backprop can't be used."]],"warp":[[0,0],[0.5,0.4],[6.04,3.2],[10.78,6],[16.56,8.8],[23.336,12]]},{"dur":28.329,"caps":[[0.5,7.47,"Keep real spikes forward; pretend a smooth sigmoid backward."],[7.72,14.21,"Its slope is a bell centred on the threshold. k = 1: peak 0.25."],[14.46,19.75,"k = 5: peak 1.25, narrower."],[20,26.17,"k = 20: peak 5. As k grows, the bell becomes the delta."]],"warp":[[0,0],[0.5,0.4],[7.72,3.2],[14.46,6],[20,8.8],[28.329,12]]},{"dur":23.754,"caps":[[0.5,6.19,"An EA can tune weights, delays, thresholds and structure."],[6.44,12.05,"Often bi-level: structure upper, weights lower."],[12.3,17.91,"30 networks a generation, 100 generations: 3000 tests."],[18.16,22.97,"Costly, and co-evolving everything at once is still open."]],"warp":[[0,0],[0.5,0.4],[6.44,3.2],[12.3,6],[18.16,8.8],[23.754,12]]},{"dur":16.649,"caps":[],"warp":[[0,0],[0.5,0.9],[5.48,2],[10.38,3.1],[16.649,9]]}]};
